WITH USERS AS ( -- This CTE retrieves the user information
    SELECT DISTINCT 
        DVO_SRC3.USER_HKEY AS BASE_OBJECT_H_KEY,
        DVO_SRC3.USER_BK AS USER_BK,
        SAT_SRC3_1_1.NAME
    FROM {{ source('eli_dv_bv', 'hub_user') }} DVO_SRC3
    INNER JOIN {{ ref('sat_ssc_user_bvv_curr') }} SAT_SRC3_1_1
        ON DVO_SRC3.USER_HKEY = SAT_SRC3_1_1.USER_HKEY
),
COMPANIES AS ( -- This CTE retrieves the company information
    SELECT DISTINCT 
        DVO_SRC1.COMPANY_HKEY AS BASE_OBJECT_H_KEY,
        DVO_SRC1.COMPANY_BK AS COMPANY_BK,
        SAT_SRC1_1_4._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP,
        SAT_SRC1_1_4.ACCOUNT_NAME,
        SAT_SRC1_1_4.ACCOUNT_TYPE,
        SAT_SRC1_1_4.WEBSITE,
        SAT_SRC1_1_4.ACCOUNT_BH_ID,
        SAT_SRC1_1_4.ACCOUNT_INDUSTRY,
        SAT_SRC1_1_4.VMS,
        SAT_SRC1_1_4.BILLING_CITY,
        SAT_SRC1_1_4.BILLING_STATE,
        SAT_SRC1_1_4.ACCOUNT_SOURCE,
        SAT_SRC1_1_4.BILLING_STREET,
        SAT_SRC1_1_4.VMS_BURDEN,
        SAT_SRC1_1_4.BILLING_COUNTRY,
        SAT_SRC1_1_4.ACCOUNT_STATUS,
        SAT_SRC1_1_4.BILLING_STATE_CODE,
        SAT_SRC1_1_4.LAST_ACTIVITY_DATE,
        SAT_SRC1_1_4.BILLING_POSTAL_CODE,
        SAT_SRC1_1_4.SAGE_COMPANY_ID,
        SAT_SRC1_1_4.ACCOUNT_ELI_LEGACY_SYSTEM_ID,
        SAT_SRC1_1_4.PARENT_ACCOUNT,
        SAT_SRC1_1_4.ACCOUNT_SOURCE_ADDITIONAL_INFORMATION,
        SAT_SRC1_1_4.ACCOUNT_VIA_SF_LEGACY_ID
    FROM {{ source('eli_dv_bv', 'hub_company') }} DVO_SRC1
    LEFT JOIN {{ ref('company_except') }} c
        ON DVO_SRC1.COMPANY_BK = c.COMPANY_BK
    INNER JOIN {{ ref('sat_ssc_company_bvv_curr') }} SAT_SRC1_1_4
        ON DVO_SRC1.COMPANY_HKEY = SAT_SRC1_1_4.COMPANY_HKEY
    WHERE c.COMPANY_BK is null
),
COMPANIES_LNK_USERS AS ( -- This CTE retrieves the user relationships for companies
    SELECT DISTINCT
        DVO_SRC2.COMPANY_HKEY AS BASE_OBJECT_H_KEY,
        DVO_SRC2.LNK_COMPANY_USER_HKEY AS BASE_OBJECT_L_H_KEY,
        DVO_SRC2.USER_HKEY AS BASE_OBJECT_F_H_KEY,
        ROW_NUMBER() OVER (
				PARTITION BY "DVO_SRC2"."COMPANY_HKEY" -- Partition by company to get the latest company
				ORDER BY "SAT_SRC2_1_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
			) AS "RN",
        SAT_SRC2_1_1._AIRBYTE_EXTRACTED_AT AS SNAPSHOT__TIMESTAMP
    FROM {{ source('eli_dv_bv', 'lnk_company_user') }} DVO_SRC2
    INNER JOIN {{ ref('lks_ssc_company_user_bvv_curr') }} SAT_SRC2_1_1
        ON DVO_SRC2.LNK_COMPANY_USER_HKEY = SAT_SRC2_1_1.LNK_COMPANY_USER_HKEY
)
    SELECT DISTINCT
        UPPER(SHA2(
			UPPER(REPLACE(COALESCE(TRIM(COMPANIES.COMPANY_BK),'~'), '\#', '\\\#')) || '\#' ||
			UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(COMPANIES.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
		)) AS DIM_COMPANY_HKEY
        , COMPANIES.BASE_OBJECT_H_KEY AS BASE_OBJECT_H_KEY
        , COMPANIES.COMPANY_BK AS COMPANY_BK
        , COMPANIES.SNAPSHOT__TIMESTAMP AS SNAPSHOT__TIMESTAMP
        , COMPANIES.ACCOUNT_NAME AS ACCOUNT_NAME
        , COMPANIES.ACCOUNT_TYPE AS ACCOUNT_TYPE
        , COMPANIES.WEBSITE AS WEBSITE
        , COMPANIES.ACCOUNT_BH_ID AS ACCOUNT_BH_ID
        , COMPANIES.ACCOUNT_INDUSTRY AS ACCOUNT_INDUSTRY
        , COMPANIES.VMS AS VMS
        , COMPANIES.BILLING_CITY AS BILLING_CITY
        , COMPANIES.BILLING_STATE AS BILLING_STATE
        , COMPANIES.ACCOUNT_SOURCE AS ACCOUNT_SOURCE
        , COMPANIES.BILLING_STREET AS BILLING_STREET
        , COMPANIES.VMS_BURDEN AS VMS_BURDEN
        , COMPANIES.BILLING_COUNTRY AS BILLING_COUNTRY
        , COMPANIES.ACCOUNT_STATUS AS ACCOUNT_STATUS
        , COMPANIES.BILLING_STATE_CODE AS BILLING_STATE_CODE
        , COMPANIES.LAST_ACTIVITY_DATE AS LAST_ACTIVITY_DATE
        , COMPANIES.BILLING_POSTAL_CODE AS BILLING_POSTAL_CODE
        , COMPANIES.SAGE_COMPANY_ID AS SAGE_COMPANY_ID
        , COMPANIES.ACCOUNT_ELI_LEGACY_SYSTEM_ID AS ACCOUNT_ELI_LEGACY_SYSTEM_ID
        , COMPANIES.PARENT_ACCOUNT AS PARENT_ACCOUNT
        , COMPANIES.ACCOUNT_SOURCE_ADDITIONAL_INFORMATION AS ACCOUNT_SOURCE_ADDITIONAL_INFORMATION
        , COMPANIES.ACCOUNT_VIA_SF_LEGACY_ID AS ACCOUNT_VIA_SF_LEGACY_ID
        , USERS.NAME AS OWNER_NAME
    FROM COMPANIES COMPANIES -- MAIN_HUB: HUB_COMPANY
    INNER JOIN COMPANIES_LNK_USERS COMPANIES_LNK_USERS
        ON COMPANIES.BASE_OBJECT_H_KEY = COMPANIES_LNK_USERS.BASE_OBJECT_H_KEY
        AND COMPANIES_LNK_USERS.RN = 1 
    INNER JOIN USERS USERS
        ON COMPANIES_LNK_USERS.BASE_OBJECT_F_H_KEY = USERS.BASE_OBJECT_H_KEY